import * as THREE from 'three';

const canvas = document.querySelector('#world');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.outputColorSpace = THREE.SRGBColorSpace;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a8c9ba');
scene.fog = new THREE.FogExp2('#a8c9ba', .0042);
const camera = new THREE.PerspectiveCamera(54, innerWidth/innerHeight, .1, 260);
const clock = new THREE.Clock();
scene.add(new THREE.HemisphereLight('#e7f2e8','#697b4f',2.05));
const sun = new THREE.DirectionalLight('#ffe3af',3.3); sun.position.set(-38,55,26); sun.castShadow=true; sun.shadow.mapSize.set(2048,2048); sun.shadow.camera.left=-55; sun.shadow.camera.right=55; sun.shadow.camera.top=55; sun.shadow.camera.bottom=-55; sun.shadow.bias=-.0002; scene.add(sun);
const mat=(color,roughness=.85)=>new THREE.MeshStandardMaterial({color,roughness});
const mats={ground:mat('#78965e'),grass:mat('#92a966'),darkGrass:mat('#627d50'),wood:mat('#765337'),wood2:mat('#9a7046'),roof:mat('#684b36'),roofLight:mat('#8d6040'),gold:mat('#d6ae58',.55),cream:mat('#e7d6a9'),water:new THREE.MeshStandardMaterial({color:'#4c9d9e',roughness:.27,metalness:.08}),leaf:mat('#51754b'),leaf2:mat('#6c8954'),leaf3:mat('#85965c'),stone:mat('#a7a58d'),path:mat('#c5ad7d'),rice:mat('#bac36d'),riceGold:mat('#d2b45f'),shirt:mat('#d7b166'),longyi:mat('#a44e3c'),skin:mat('#c89068'),black:mat('#292b27')};
function mesh(geo,material,parent=scene){const o=new THREE.Mesh(geo,material);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function box(parent,material,pos,size){const o=mesh(new THREE.BoxGeometry(...size),material,parent);o.position.set(...pos);return o}
function ball(parent,material,pos,scale,segments=12){const o=mesh(new THREE.SphereGeometry(1,segments,segments),material,parent);o.position.set(...pos);o.scale.set(...scale);return o}
function cylinder(parent,material,pos,r1,r2,h,segments=8){const o=mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,parent);o.position.set(...pos);return o}
function cone(parent,material,pos,r,h,segments=8){const o=mesh(new THREE.ConeGeometry(r,h,segments),material,parent);o.position.set(...pos);return o}
function group(parent=scene){const g=new THREE.Group();parent.add(g);return g}

// A wide, continuous valley floor with gently rolling green shoulders.
const floor=mesh(new THREE.PlaneGeometry(220,220,1,1),mats.ground);floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;
const hillMat=mat('#718c5e');
for(let i=0;i<11;i++){const a=i/11*Math.PI*2;const h=5+Math.random()*7;const o=mesh(new THREE.SphereGeometry(1,16,12),hillMat);o.position.set(Math.cos(a)*76,h-5,Math.sin(a)*74-12);o.scale.set(30,h,24);o.receiveShadow=true;o.castShadow=false;}
// Misty, layered Shan hills in the distance.
for(let row=0;row<3;row++)for(let i=0;i<12;i++){const x=-105+i*19+(row%2)*8,z=-100-row*19;const h=18+Math.sin(i*1.7+row)*7;const m=mesh(new THREE.ConeGeometry(15,h,7),mat(row===0?'#6d897d':row===1?'#81998a':'#93a999'));m.position.set(x,h*.38,z);m.rotation.y=i*.4;m.castShadow=false;}

// Winding, reflective river with softly raised banks.
function riverStrip(points,width,material,y){const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(p[0],y,p[1])));const verts=[],indices=[];const n=120;for(let i=0;i<=n;i++){const t=i/n,p=curve.getPoint(t),tan=curve.getTangent(t),side=new THREE.Vector3(-tan.z,0,tan.x).normalize();const w=width*(.72+.28*Math.sin(t*Math.PI));verts.push(p.x+side.x*w,p.y,p.z+side.z*w,p.x-side.x*w,p.y,p.z-side.z*w);if(i<n){let k=i*2;indices.push(k,k+1,k+2,k+1,k+3,k+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(indices);g.computeVertexNormals();const m=mesh(g,material);m.material.side=THREE.DoubleSide;m.castShadow=false;return curve}
const riverCurve=riverStrip([[-100,-21],[-65,-17],[-43,-19],[-21,-13],[0,-17],[20,-11],[43,-16],[70,-8],[105,-11]],5.2,mats.water,.03);
const bankMat=mat('#a3a273');riverStrip([[-100,-19.7],[-65,-15.7],[-43,-17.7],[-21,-11.7],[0,-15.7],[20,-9.7],[43,-14.7],[70,-6.7],[105,-9.7]],7.1,bankMat,-.04);

// Dirt walking paths and courtyard.
function path(points,width,color=mats.path){const c=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(p[0],.015,p[1])));const v=[],ind=[],steps=80;for(let i=0;i<=steps;i++){const p=c.getPoint(i/steps),t=c.getTangent(i/steps),s=new THREE.Vector3(-t.z,0,t.x).normalize();v.push(p.x+s.x*width,p.y,p.z+s.z*width,p.x-s.x*width,p.y,p.z-s.z*width);if(i<steps){const k=i*2;ind.push(k,k+1,k+2,k+1,k+3,k+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(ind);g.computeVertexNormals();const m=mesh(g,color);m.material.side=THREE.DoubleSide;m.receiveShadow=true;m.castShadow=false}
path([[0,28],[0,20],[0,11],[2,4],[4,-2],[6,-8],[10,-15]],2.2);
path([[4,4],[11,4],[18,1],[23,-2]],1.2);
path([[-2,5],[-8,4],[-14,2],[-20,0]],1.4);

// Rice paddies: bunds, shallow water and individual lush rows.
const plots=[];
function makePlot(x,z,w=8,d=6,index=0){const g=group();g.position.set(x,0,z);const bund=mesh(new THREE.BoxGeometry(w,.2,d),mat('#a89562'),g);bund.position.y=.02;const wet=mesh(new THREE.BoxGeometry(w-.5,.09,d-.5),new THREE.MeshStandardMaterial({color:'#789f82',roughness:.4,metalness:.08}),g);wet.position.y=.14;wet.receiveShadow=true;const cropGroup=group(g);const plot={group:g,crops:cropGroup,x,z,w,d,state:index===0?'growing':'ready',progress:index===0?.45:1};plots.push(plot);seedCrops(plot);return plot}
function seedCrops(plot){while(plot.crops.children.length)plot.crops.remove(plot.crops.children[0]);const rows=6,cols=11;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let px=-plot.w*.4+c*(plot.w*.8/(cols-1)),pz=-plot.d*.36+r*(plot.d*.72/(rows-1));if(plot.state==='plowed')continue;const height=plot.state==='seeded'?.12:plot.state==='growing'?.34+plot.progress*.52:.88;const stalk=mesh(new THREE.CylinderGeometry(.035,.05,height,4),plot.state==='ready'?mats.riceGold:mats.rice,plot.crops);stalk.position.set(px,.2+height/2,pz);stalk.castShadow=false;if(plot.state==='ready'){const grain=ball(plot.crops,mats.riceGold,[px,.2+height,pz],[.08,.12,.08],6);grain.castShadow=false}}}
makePlot(-17,-2,9,7,0);makePlot(-28,-8,8,7,1);makePlot(-17,-12,9,7,2);makePlot(26,-2,9,8,3);

// Timber stilt houses with woven walls and layered Shan-style roofs.
function roof(parent,x,y,z,w,d,material=mats.roof){const top=box(parent,material,[x,y,z],[w,.25,d]);top.rotation.z=.02;const ridge=box(parent,material,[x,y+.38,z],[w*.85,.35,.32]);for(const side of [-1,1]){const e=box(parent,material,[x,y-.22,z+side*d*.31],[w*1.08,.18,d*.5]);e.rotation.x=side*-.20;}return top}
function house(x,z,scale=1){const g=group();g.position.set(x,0,z);const s=scale;for(let i=0;i<4;i++){const xx=(i%2?1:-1)*1.25*s,zz=(i<2?1:-1)*.92*s;cylinder(g,mats.wood,[xx,.82*s,zz],.12*s,.16*s,1.65*s,7)}box(g,mats.wood2,[0,1.55*s,0],[3.1*s,1.4*s,2.4*s]);for(let i=0;i<3;i++){box(g,mat(i===1?'#b18a57':'#9c784f'),[0,1.4*s,(i-1)*.58*s],[3.14*s,.14*s,.06*s])}roof(g,0,2.55*s,0,3.8*s,3.4*s);box(g,mats.wood,[0,.32*s,0],[.9*s,.16*s,.62*s]);for(let i=0;i<4;i++)box(g,mats.wood2,[(-1.3+i*.85)*s,.3*s,1.5*s],[.08*s,.62*s,.08*s]);return g}
house(-7,1,1.12);house(12,1,.95);house(20,-8,.85);house(-26,5,.88);
// House lanterns / doorway accents
for(const [x,z] of [[-7,1],[12,1],[20,-8],[-26,5]]){const lamp=ball(scene,mat('#e8b967'),[x+1,2.2,z+1.6],[.09,.12,.09]);lamp.material.emissive=new THREE.Color('#c97626');lamp.material.emissiveIntensity=.7;}

// A luminous, tiered pagoda and monastery complex.
const pagoda=group();pagoda.position.set(29,0,7);
cylinder(pagoda,mats.stone,[0,.24,0],4.7,5.3,.48,12);cylinder(pagoda,mats.cream,[0,.53,0],3.7,4.2,.22,12);
cylinder(pagoda,mats.gold,[0,1.15,0],2.65,3.35,1.1,12);cone(pagoda,mats.gold,[0,2.35,0],2.85,1.6,12);cylinder(pagoda,mats.cream,[0,2.65,0],1.85,2.3,.22,12);cone(pagoda,mats.gold,[0,3.8,0],2.05,2.3,12);cylinder(pagoda,mats.gold,[0,4.4,0],1.15,1.4,.5,12);cone(pagoda,mats.gold,[0,5.7,0],1.4,2.5,12);cylinder(pagoda,mats.gold,[0,7.3,0],.12,.35,.8,8);cone(pagoda,mats.gold,[0,8,0],.38,1.1,8);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const b=ball(pagoda,mats.gold,[Math.cos(a)*3.3,.65,Math.sin(a)*3.3],[.13,.32,.13],8);}
// monastery hall
const monastery=house(36,-1,1.5);monastery.rotation.y=-.5;

// Tree clusters, palms and flowering shrubs.
function tree(x,z,scale=1,palm=false,variant=0){const g=group();g.position.set(x,0,z);const trunk=cylinder(g,mat('#76533b'),[0,1.2*scale,0],.18*scale,.28*scale,2.4*scale,7);if(palm){cylinder(g,mat('#76533b'),[0,2.4*scale,0],.18*scale,.18*scale,2.5*scale,7);for(let i=0;i<8;i++){const a=i*Math.PI/4;const fr=box(g,mat(i%2?'#4b784f':'#618b54'),[Math.cos(a)*.95*scale,3.45*scale,Math.sin(a)*.95*scale],[.18*scale,1.45*scale,.48*scale]);fr.rotation.z=Math.cos(a)*-.56;fr.rotation.x=Math.sin(a)*.56;}ball(g,mat('#668b51'),[0,3.15*scale,0],[.34*scale,.3*scale,.34*scale],8)}else{const colors=[mats.leaf,mats.leaf2,mats.leaf3];ball(g,colors[variant%3],[0,3*scale,0],[1.35*scale,1.25*scale,1.28*scale],9);ball(g,colors[(variant+1)%3],[-.65*scale,2.85*scale,.25*scale],[.82*scale,.92*scale,.8*scale],8);ball(g,colors[(variant+2)%3],[.65*scale,2.8*scale,-.25*scale],[.9*scale,.84*scale,.9*scale],8)}return g}
const reserved=[[-7,1],[12,1],[20,-8],[-26,5],[29,7],[36,-1],[0,14],[-17,-2],[-28,-8],[-17,-12],[26,-2]];
for(let i=0;i<105;i++){const x=(Math.random()-.5)*175,z=(Math.random()-.5)*170;if(z>-3&&z<14&&x>-34&&x<40)continue;if(Math.hypot(x,z+17)<10)continue;if(reserved.some(p=>Math.hypot(x-p[0],z-p[1])<7))continue;tree(x,z,.65+Math.random()*.7,Math.random()<.12,i%3)}
for(const p of [[-37,5],[40,13],[15,-24],[-42,-25],[51,-26],[5,30]])tree(...p,1.25,true);
// Flowers and stones along the paths
for(let i=0;i<90;i++){const x=(Math.random()-.5)*62,z=(Math.random()-.5)*55;if(Math.abs(x)<4&&z>3)continue;const b=ball(scene,mat(['#e4d7a2','#cfb77b','#7e995b'][i%3]),[x,.12,z],[.12,.13,.12],6);b.castShadow=false;}

// Character builder: longyi, cotton shirt, headwrap and sandals.
function makePerson(shirtColor,longyiColor,hat=false){const root=group();const model=group(root);const shirt=mat(shirtColor),longyi=mat(longyiColor);cylinder(model,longyi,[0,.62,0],.29,.34,.72,9);box(model,shirt,[0,1.23,0],[.58,.72,.36]);ball(model,mats.skin,[0,1.78,0],[.23,.27,.22],12);if(hat){const h=mesh(new THREE.CylinderGeometry(.24,.27,.12,10),mats.gold,model);h.position.y=2.04;const crown=mesh(new THREE.CylinderGeometry(.15,.19,.16,9),mat('#b14d3d'),model);crown.position.y=2.16;}else{const wrap=mesh(new THREE.TorusGeometry(.23,.065,5,12),mat('#c4a25a'),model);wrap.position.y=1.98;wrap.rotation.x=Math.PI/2;}const eyeMat=mat('#292720');ball(model,eyeMat,[-.08,1.8,-.195],[.025,.025,.02],6);ball(model,eyeMat,[.08,1.8,-.195],[.025,.025,.02],6);const arms=[];for(const side of [-1,1]){const arm=mesh(new THREE.CapsuleGeometry(.085,.45,3,6),shirt,model);arm.position.set(side*.39,1.22,0);arm.rotation.z=side*-.14;arms.push(arm);const leg=mesh(new THREE.CapsuleGeometry(.105,.4,3,6),longyi,model);leg.position.set(side*.17,.2,0);const sandal=box(model,mats.wood,[side*.17,-.05,-.05],[.22,.08,.36]);}root.userData={model,arms,shirt,longyi};return root}
const player=makePerson('#d4ad62','#a94e3d',false);player.position.set(0,0,15);player.scale.setScalar(1.05);scene.add(player);
function addVillager(x,z,shirt,longyi,opts={}){const p=makePerson(shirt,longyi,opts.hat);p.position.set(x,0,z);if(opts.rotation)p.rotation.y=opts.rotation;scene.add(p);return p}
const daw=addVillager(4,4,'#789b76','#62483f',{rotation:.15});
const merchant=addVillager(23,-2,'#b77953','#384e50',{hat:true,rotation:-.5});
const monk=addVillager(34,5,'#aa6548','#7d493a',{rotation:2.4});

// Small animals with readable silhouettes and gentle idle animation.
function animal(x,z,type='cow'){const g=group();g.position.set(x,0,z);if(type==='cow'){ball(g,mat('#d9d4c5'),[0,.62,0],[.75,.48,.42]);ball(g,mat('#443e35'),[-.2,.88,.29],[.22,.17,.08]);ball(g,mat('#443e35'),[.25,.46,-.37],[.18,.13,.08]);ball(g,mat('#d9d4c5'),[0,.85,-.37],[.32,.32,.29]);ball(g,mat('#443e35'),[.04,.9,-.6],[.24,.2,.08]);for(let s of [-1,1]){cylinder(g,mat('#d4d0c3'),[s*.42,.23,-.1],.07,.08,.46,6);const ear=ball(g,mat('#d9d4c5'),[s*.32,.98,-.38],[.19,.07,.09],6);ear.rotation.z=s*.3}}else{ball(g,mat(type==='duck'?'#d9b746':'#eee1c4'),[0,.27,0],[.32,.22,.24],8);ball(g,mat(type==='duck'?'#d9b746':'#eee1c4'),[0,.48,-.15],[.16,.16,.15],8);if(type==='duck')box(g,mat('#d5713d'),[0,.44,-.31],[.15,.06,.12]);for(let s of [-1,1])cylinder(g,mat('#a77c43'),[s*.12,.07,0],.025,.025,.14,5)}scene.add(g);g.userData.phase=Math.random()*6;return g}
const animals=[animal(-12,10,'cow'),animal(-15,11,'cow'),animal(15,9,'chicken'),animal(17,10,'chicken'),animal(18,9,'duck')];

// Interactable stations and world markers.
const stations=[{name:'Daw Mya',kind:'npc',x:4,z:4,range:3.2},{name:'Morning market',kind:'shop',x:23,z:-2,range:3.6},{name:'Rice paddy',kind:'plot',x:-17,z:-2,range:5.2},{name:'Rice paddy',kind:'plot',x:-28,z:-8,range:5.2},{name:'Rice paddy',kind:'plot',x:-17,z:-12,range:5.2},{name:'Rice paddy',kind:'plot',x:26,z:-2,range:5.4},{name:'Lakeside',kind:'fish',x:3,z:-16,range:5.4},{name:'Cooking fire',kind:'cook',x:-4,z:3,range:3.5},{name:'Build a home',kind:'build',x:-8,z:1,range:4.5},{name:'Golden pagoda',kind:'pagoda',x:29,z:7,range:4.8}];
const fire=group();fire.position.set(-4,0,3);cylinder(fire,mats.stone,[0,.13,0],.5,.57,.22,8);for(let i=0;i<3;i++){const log=box(fire,mats.wood,[0,.28,0],[.75,.12,.14]);log.rotation.y=i*1.04;}const flame=cone(fire,mat('#e78c3e'),[0,.6,0],.23,.72,7);flame.material.emissive=new THREE.Color('#e75e1c');flame.material.emissiveIntensity=1.2;const glow=new THREE.PointLight('#ffad54',1.8,9);glow.position.set(0,1,0);fire.add(glow);

input.newString:
fire.add(glow);

const saved=(()=>{try{return JSON.parse(localStorage.getItem('golden-fields-save')||'{}')}catch{return {}}})();
const state={rice:saved.rice||0,fish:saved.fish||0,wood:saved.wood??8,coins:saved.coins??24,days:saved.days||1,questDone:saved.questDone||false,harvested:saved.harvested||0,cooked:saved.cooked||0,weather:'Clear skies',time:.28,angle:0,toastTimer:0,dayLength:420,buildings:saved.buildings||0};
function save(){localStorage.setItem('golden-fields-save',JSON.stringify({rice:state.rice,fish:state.fish,wood:state.wood,coins:state.coins,days:state.days,questDone:state.questDone,harvested:state.harvested,cooked:state.cooked,buildings:state.buildings}))}
function updateHud(){document.querySelector('#riceCount').textContent=state.rice;document.querySelector('#fishCount').textContent=state.fish;document.querySelector('#woodCount').textContent=state.wood;document.querySelector('#coinCount').textContent=state.coins;document.querySelector('#questCount').textContent=`${Math.min(state.harvested,3)} / 3 bundles`;document.querySelector('#questProgress').style.width=`${Math.min(state.harvested/3,1)*100}%`;document.querySelector('#dayLabel').textContent=`DAY ${String(state.days).padStart(2,'0')}`;save()}
updateHud();
function toast(title,text){const el=document.querySelector('#toast');document.querySelector('#toastTitle').textContent=title;document.querySelector('#toastText').textContent=text;el.classList.add('show');state.toastTimer=3.5}
function notice(text){const n=document.createElement('div');n.className='toast-note';n.textContent=text;document.querySelector('#modalRoot').append(n);setTimeout(()=>n.remove(),2900)}
function showModal(title,eyebrow,description,options=[],foot=''){const root=document.querySelector('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-top"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div><button class="modal-close" aria-label="Close">×</button></div><p>${description}</p><div class="modal-options">${options.map((o,i)=>`<button data-option="${i}"><span>${o.label}</span><small>${o.cost||'→'}</small></button>`).join('')}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`;root.querySelector('.modal-close').onclick=()=>root.innerHTML='';root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelectorAll('[data-option]').forEach((b,i)=>b.onclick=()=>options[i].run())}
function currentStation(){let nearest=null,dist=Infinity;for(const s of stations){const d=Math.hypot(player.position.x-s.x,player.position.z-s.z);if(d<s.range&&d<dist){nearest=s;dist=d}}return nearest}
function updatePrompt(){const s=currentStation(),p=document.querySelector('#prompt');if(s){p.classList.add('show');document.querySelector('#promptText').textContent=s.kind==='npc'?'Talk to Daw Mya':s.kind==='plot'?'Tend the rice paddy':s.kind==='fish'?'Cast your fishing line':s.kind==='shop'?'Browse the morning market':s.kind==='cook'?'Cook a meal':s.kind==='build'?'Build & customize':s.kind==='pagoda'?'Visit the golden pagoda':s.name;document.querySelector('#actionLabel').textContent=s.kind==='plot'?(plots[stations.filter(a=>a.kind==='plot').indexOf(s)]?.state==='ready'?'HARVEST':'TEND'):s.kind==='fish'?'FISH':s.kind==='shop'?'TRADE':s.kind==='build'?'BUILD':'INTERACT';document.querySelector('#actionIcon').textContent=s.kind==='plot'?'♧':s.kind==='fish'?'⌁':s.kind==='shop'?'◉':'✦'}else{p.classList.remove('show');document.querySelector('#actionLabel').textContent='INTERACT';document.querySelector('#actionIcon').textContent='✦'}}
function talkToDaw(){if(state.questDone){showModal('A kind heart','DAW MYA','“You brought life back to our fields. Take this for the road, dear.”', [{label:'Thank her',run:()=>{state.coins+=3;updateHud();document.querySelector('#modalRoot').innerHTML='';toast('Village blessing','Daw Mya gave you 3 kyat.')}}]);return}showModal('A little help?','DAW MYA · YOUR NEIGHBOR','“The morning market is waiting, and my old hands are slow today. Could you gather three bundles of rice for me?”',[{label:'I’ll help with the harvest',run:()=>{document.querySelector('#modalRoot').innerHTML='';toast('Quest accepted','Harvest 3 bundles from the rice paddies.')}},{label:'Maybe later',run:()=>document.querySelector('#modalRoot').innerHTML=''}],'TIP · Look for the golden rice stalks in the nearby paddies.')}
