function openMarket(){showModal('The morning market','THU · VILLAGE TRADER','“Fresh from the valley, fair prices for a neighbor.” Trade your harvest and stock up on supplies.',[{label:'Sell 1 rice bundle',cost:'+8 kyat',run:()=>{if(state.rice<1){notice('You have no rice to sell.');return}state.rice--;state.coins+=8;updateHud();document.querySelector('#modalRoot').innerHTML='';toast('Trade complete','One bundle sold for 8 kyat.')}},{label:'Buy timber',cost:'−5 kyat · +3 timber',run:()=>{if(state.coins<5){notice('You need 5 kyat.');return}state.coins-=5;state.wood+=3;updateHud();document.querySelector('#modalRoot').innerHTML='';toast('Timber purchased','Three sturdy pieces added to your satchel.')}},{label:'Buy fishing bait',cost:'−2 kyat',run:()=>{if(state.coins<2){notice('You need 2 kyat.');return}state.coins-=2;updateHud();document.querySelector('#modalRoot').innerHTML='';toast('Bait packed','The lake is full of fish this morning.')}}])}
