function jump(){if(player.position.y<.05){player.userData.jump=5.1}}

const keys=new Set();let joy={x:0,y:0};let dragging=false,lastX=0,lastY=0;
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key.toLowerCase()==='e')interact();if(e.code==='Space')jump();if(e.key==='Escape')document.querySelector('#modalRoot').innerHTML=''});
addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX;state.angle-=dx*.0042;lastX=e.clientX;lastY=e.clientY});
canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);
const stick=document.querySelector('#joystick'),knob=document.querySelector('#stickKnob');let stickPointer=null;
stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});
stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});
function moveStick(e){const r=stick.querySelector('.stick-base').getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy;const max=31,l=Math.hypot(dx,dy);if(l>max){dx=dx/l*max;dy=dy/l*max}joy.x=dx/max;joy.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}
function releaseStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;joy={x:0,y:0};knob.style.transform='translate(0,0)'}stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);
document.querySelector('#actionBtn').addEventListener('click',interact);document.querySelector('#jumpBtn').addEventListener('click',jump);
document.querySelector('#questToggle').onclick=()=>document.querySelector('#questCard').classList.toggle('collapsed');
document.querySelector('#questPin').onclick=()=>{toast('Quest tracked','Daw Mya is waiting near the village path.');};
document.querySelector('#craftBtn').onclick=()=>showModal('Craft & cook','YOUR HOMESTEAD','Make something useful from the things you gather.',[{label:'Cook a meal',cost:'At the fire',run:()=>{document.querySelector('#modalRoot').innerHTML='';openCooking()}},{label:'Build a garden bed',cost:'3 timber · 4 kyat',run:()=>{document.querySelector('#modalRoot').innerHTML='';openBuild()}}]);
document.querySelector('#bagBtn').onclick=()=>showModal('Your satchel','INVENTORY','A few things gathered from a life well lived.',[{label:`Rice bundles · ${state.rice}`,run:()=>document.querySelector('#modalRoot').innerHTML=''},{label:`Fresh fish · ${state.fish}`,run:()=>document.querySelector('#modalRoot').innerHTML=''},{label:`Timber · ${state.wood}`,run:()=>document.querySelector('#modalRoot').innerHTML=''},{label:`Kyat · ${state.coins}`,run:()=>document.querySelector('#modalRoot').innerHTML=''}]);
document.querySelector('#profileBtn').onclick=()=>showModal('Your village life','CHARACTER','You are Thura, a young farmer returning to the valley where your family has lived for generations.',[{label:'Traditional Shan longyi',run:()=>document.querySelector('#modalRoot').innerHTML=''},{label:'Reset saved game',run:()=>{localStorage.removeItem('golden-fields-save');location.reload()}}],'Your progress is saved automatically on this device.');
document.querySelector('#mapBtn').onclick=()=>notice('Explore the valley · follow the footpaths');
let soundOn=false;document.querySelector('#soundBtn').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';notice(soundOn?'Ambient sound is ready':'Sound muted')};

// Draw an illustrated, live minimap of the nearby countryside.
const mapCanvas=document.querySelector('#minimap'),mctx=mapCanvas.getContext('2d');
